def decide(recipient_reputation: float, round_num: int, my_history: list[dict]) -> bool:
    # Base threshold: start moderate, become slightly more generous over time.
    base_threshold = 0.25 - round_num * 0.02
    # Personal history modulation: if we have been donating frequently,
    # we become stricter (punish low reputation); if stingy, more generous.
    if len(my_history) >= 4:
        recent = my_history[-4:]
        donated = sum(1 for h in recent if h.get("action") == "donate")
        if donated >= 3:
            base_threshold += 0.15  # stricter when generous
        elif donated <= 1:
            base_threshold -= 0.1  # more lenient when stingy
